{"content":"//! Unit tests, translated from the C source `test.c`.

use totp::{from_base32, hotp, hmac_sha1, pack32, sha1, unpack32, unpack64};

fn to_hex(a: &[u8], buf: &mut [u8]) {
    for (i, &byte) in a.iter().enumerate() {
        buf[i * 2] = b"0123456789abcdef"[byte >> 4];
        buf[i * 2 + 1] = b"0123456789abcdef"[byte & 0xF];
    }
    buf[a.len() * 2] = b'\0';
}

#[test]
fn test_pack() {
    let mut a = [0u8; 8];

    unpack32(0x12345678, &mut a[0..4].try_into().unwrap());
    assert_eq!(a[0], 0x12);
    assert_eq!(a[1], 0x34);
    assert_eq!(a[2], 0x56);
    assert_eq!(a[3], 0x78);

    unpack64(0x123456789ABCDEF0, &mut a);
    assert_eq!(a[0], 0x12);
    assert_eq!(a[1], 0x34);
    assert_eq!(a[2], 0x56);
    assert_eq!(a[3], 0x78);
    assert_eq!(a[4], 0x9A);
    assert_eq!(a[5], 0xBC);
    assert_eq!(a[6], 0xDE);
    assert_eq!(a[7], 0xF0);

    assert_eq!(pack32(&a[0..4].try_into().unwrap()), 0x12345678);
}

#[test]
fn test_sha1() {
    let mut buf = [0u8; 512];
    let mut hash = [0u8; 20];
    let mut str = [0u8; 41];

    sha1(&mut buf, 0, buf.len(), &mut hash);
    to_hex(&hash, &mut str);
    assert_eq!(
        std::str::from_utf8(&str[..40]).unwrap(),
        "da39a3ee5e6b4b0d3255bfef95601890afd80709"
    );

    let abc = b"abc";
    buf[..3].copy_from_slice(abc);
    sha1(&mut buf, 3, buf.len(), &mut hash);
    to_hex(&hash, &mut str);
    assert_eq!(
        std::str::from_utf8(&str[..40]).unwrap(),
        "a9993e364706816aba3e25717850c26c9cd0d89d"
    );

    let fox = b"The quick brown fox jumps over the lazy dog";
    buf[..fox.len()].copy_from_slice(fox);
    sha1(&mut buf, fox.len(), buf.len(), &mut hash);
    to_hex(&hash, &mut str);
    assert_eq!(
        std::str::from_utf8(&str[..40]).unwrap(),
        "2fd4e1c67a2d28fced849ee1bb76e7391b93eb12"
    );
}

#[test]
fn test_hmac_sha1() {
    let mut key = [0u8; 64];
    let mut text = [0u8; 64];
    let mut hash = [0u8; 20];
    let mut str = [0u8; 41];

    // RFC 2202
    for i in 0..20 {
        key[i] = 0xAA;
    }
    for i in 0..50 {
        text[i] = 0xDD;
    }

    hmac_sha1(&key, &text, 50, &mut hash);
    to_hex(&hash, &mut str);
    assert_eq!(
        std::str::from_utf8(&str[..40]).unwrap(),
        "125d7342b9ac11cd91a39af48aa17b4f63f175d3"
    );
}

#[test]
fn test_hotp() {
    // Appendix D
